\begin{itemchoice}
			\itemch Hình chiếu của điểm $B(-1;2;3)$ lên mặt phẳng $(Oxz)$ là $B'(-1;0;3)$, do đó mệnh đề sai.
			\itemch Ta có $\vec{AB}=(-1;-3;-4)$ và $\vec{AC}=(3;-5;-16)$. Suy ra $[\vec{AB},\vec{AC}] = (28;-28;14) = 14(2;-2;1)$. Vậy một vectơ pháp tuyến của mặt phẳng $(ABC)$ là $\vec{n}=(2;-2;1)$, do đó mệnh đề đúng.
			\itemch Mặt phẳng $(ABC)$ đi qua $A(0;5;7)$ và nhận $\vec{n}=(2;-2;1)$ làm vectơ pháp tuyến có phương trình: $2(x-0)-2(y-5)+1(z-7)=0 \Leftrightarrow 2x-2y+z+3=0$, do đó mệnh đề sai.
			\itemch Bán kính mặt cầu tâm $S$ tiếp xúc với mặt phẳng $(ABC)$ là $\displaystyle R = \mathrm{d}(S,(ABC)) = \frac{|2(1)-2(-2)+3+3|}{\sqrt{2^2+(-2)^2+1^2}} = \frac{12}{3} = 4$. Phương trình mặt cầu là $(x-1)^2+(y+2)^2+(z-3)^2=16$, do đó mệnh đề đúng.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có $P(\overline{B})=1-P(B)=1-0{,}6=0{,}4$, do đó mệnh đề đúng.
			\itemch Theo công thức ta có $\displaystyle P(A|\overline{B}) = \frac{P(A\cap\overline{B})}{P(\overline{B})} \Rightarrow P(A\cap\overline{B}) = 0{,}2 \cdot 0{,}4 = 0{,}08$. Lại có $P(A) = P(A\cap B) + P(A\cap\overline{B}) \Rightarrow P(A\cap B) = 0{,}3 - 0{,}08 = 0{,}22 \neq 0{,}3$, do đó mệnh đề sai.
			\itemch Từ tính toán trên ta có $P(A\cap\overline{B})=0{,}08 \neq 0{,}1$, do đó mệnh đề sai.
			\itemch Ta có $\displaystyle P(A|B) = \frac{P(A\cap B)}{P(B)} = \frac{0{,}22}{0{,}6} \approx 0{,}367 \neq 0{,}75$, do đó mệnh đề sai.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có $\vec{AB}=(-2;2;-1)$. Bán kính mặt cầu là $R=AB=\sqrt{(-2)^2+2^2+(-1)^2}=\sqrt{9}=3$. Phương trình mặt cầu $(S)$ là $x^2+(y-4)^2+(z-2)^2=9$, do đó mệnh đề sai.
			\itemch Đường thẳng $AB$ có $\vec{u_{AB}}=(-2;2;-1)$, đường thẳng $d$ có $\vec{u_d}=(1;5;-1)$. Ta có $\displaystyle \cos(AB,d) = \frac{|-2\cdot 1+2\cdot 5+(-1)\cdot (-1)|}{\sqrt{4+4+1}\sqrt{1+25+1}} = \frac{9}{3\sqrt{27}} = \frac{1}{\sqrt{3}} \Rightarrow (AB,d) \approx 54^\circ 44'$, do đó mệnh đề sai.
			\itemch Đường thẳng $AB$ đi qua $A(0;4;2)$ và có VTCP $\vec{AB}=(-2;2;-1)$ nên PTTS là $\begin{cases} x=-2t \\ y=4+2t \\ z=2-t \end{cases}$. Đường thẳng $AB$ đi qua $B(-2;6;1)$ và có VTCP $\vec{AB}=(-2;2;-1)$ nên PTCT là $\displaystyle \frac{x+2}{-2}=\frac{y-6}{2}=\frac{z-1}{-1}$, do đó mệnh đề đúng.
			\itemch Giao điểm $M$ của $AB$ và $d$ thỏa hệ phương trình: $\begin{cases} -2t' = -6+t \\ 4+2t' = -2+5t \\ 2-t' = 2-t \end{cases} \Leftrightarrow \begin{cases} t'=2 \\ t=2 \end{cases}$. Suy ra $M(-4;8;0)$. Do đó $a=-4, b=8, c=0$ suy ra $b-a+c=8-(-4)+0=12$, do đó mệnh đề đúng.
		\end{itemchoice}
